I’ll make this as a self-contained arcade-sorter: conveyor belt items, matching lunchboxes, score/combo/misses, simple controls, and mobile-friendly tap/drag play.

Absolutely. Save this as lunchbox-conveyor.html and open it in a browser. 🍎

HTML
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8" />
<meta name="viewport" content="width=device-width, initial-scale=1.0" />
<title>Lunchbox Conveyor</title>
<style>
  * { box-sizing: border-box; }
  body {
    margin: 0;
    font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
    background: #fff4d8;
    color: #332414;
    overflow-x: hidden;
  }
  .game {
    max-width: 980px;
    margin: 0 auto;
    padding: 14px;
  }
  header {
    display: flex;
    justify-content: space-between;
    gap: 12px;
    align-items: center;
    margin-bottom: 10px;
    flex-wrap: wrap;
  }
  h1 {
    margin: 0;
    font-size: clamp(1.4rem, 4vw, 2.3rem);
  }
  .hud {
    display: flex;
    gap: 8px;
    flex-wrap: wrap;
  }
  .pill {
    background: white;
    border: 2px solid #e1b85b;
    border-radius: 999px;
    padding: 7px 12px;
    font-weight: 800;
    box-shadow: 0 3px 0 #d6a24c;
  }
  .panel {
    background: #fffaf0;
    border: 3px solid #d99b39;
    border-radius: 22px;
    padding: 12px;
    box-shadow: 0 6px 0 #b87827;
  }
  .belt-wrap {
    position: relative;
    height: 190px;
    overflow: hidden;
    margin-bottom: 14px;
  }
  .belt {
    position: absolute;
    inset: 48px 0 34px;
    background:
      repeating-linear-gradient(90deg, #7a5a42 0 34px, #8d6b50 34px 68px);
    border: 5px solid #503621;
    border-radius: 26px;
    box-shadow: inset 0 0 0 5px rgba(255,255,255,.12);
  }
  .belt::after {
    content: "SORT BEFORE RECESS!";
    position: absolute;
    left: 50%;
    top: 50%;
    transform: translate(-50%, -50%);
    color: rgba(255,255,255,.25);
    font-weight: 900;
    letter-spacing: 2px;
    white-space: nowrap;
  }
  .item {
    position: absolute;
    top: 70px;
    width: 76px;
    height: 76px;
    border-radius: 20px;
    background: white;
    border: 3px solid #3d2b1d;
    display: grid;
    place-items: center;
    font-size: 42px;
    cursor: grab;
    user-select: none;
    touch-action: none;
    box-shadow: 0 6px 0 rgba(0,0,0,.22);
    z-index: 3;
  }
  .item.dragging {
    cursor: grabbing;
    z-index: 10;
    transform: scale(1.08);
  }
  .lunchboxes {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 12px;
  }
  .box {
    min-height: 142px;
    border-radius: 22px;
    padding: 12px;
    text-align: center;
    border: 4px solid #3a2b1a;
    background: #fff;
    box-shadow: 0 6px 0 rgba(0,0,0,.22);
    transition: .12s;
  }
  .box strong {
    display: block;
    font-size: 1.05rem;
    margin-bottom: 8px;
  }
  .box .emoji {
    font-size: 42px;
  }
  .box.good {
    transform: translateY(-5px) scale(1.03);
    background: #d7ffd8;
  }
  .box.bad {
    animation: shake .25s;
    background: #ffd7d7;
  }
  @keyframes shake {
    0%, 100% { transform: translateX(0); }
    25% { transform: translateX(-6px); }
    75% { transform: translateX(6px); }
  }
  .controls {
    margin-top: 14px;
    display: flex;
    gap: 10px;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
  }
  button {
    border: 0;
    border-radius: 16px;
    padding: 12px 16px;
    font-weight: 900;
    font-size: 1rem;
    background: #ffcf4d;
    color: #332414;
    box-shadow: 0 5px 0 #b87827;
    cursor: pointer;
  }
  button:active { transform: translateY(3px); box-shadow: 0 2px 0 #b87827; }
  .help {
    font-weight: 700;
    opacity: .8;
  }
  .overlay {
    position: fixed;
    inset: 0;
    background: rgba(44,29,14,.72);
    display: grid;
    place-items: center;
    padding: 18px;
    z-index: 50;
  }
  .card {
    max-width: 520px;
    background: #fffaf0;
    border: 4px solid #d99b39;
    border-radius: 26px;
    padding: 22px;
    text-align: center;
    box-shadow: 0 9px 0 #8e581d;
  }
  .card h2 { margin-top: 0; font-size: 2rem; }
  .hidden { display: none; }

  @media (max-width: 680px) {
    .belt-wrap { height: 170px; }
    .item {
      width: 64px;
      height: 64px;
      font-size: 34px;
      top: 72px;
    }
    .lunchboxes {
      grid-template-columns: repeat(2, 1fr);
    }
    .box {
      min-height: 118px;
      padding: 10px;
    }
    .box .emoji { font-size: 34px; }
    .controls { justify-content: center; text-align: center; }
  }
</style>
</head>
<body>
<div class="game">
  <header>
    <h1>Lunchbox Conveyor</h1>
    <div class="hud">
      <div class="pill">Score: <span id="score">0</span></div>
      <div class="pill">Combo: <span id="combo">0</span></div>
      <div class="pill">Misses: <span id="misses">0</span>/5</div>
      <div class="pill">Time: <span id="time">60</span>s</div>
    </div>
  </header>

  <section class="panel belt-wrap" id="playArea">
    <div class="belt"></div>
  </section>

  <section class="lunchboxes">
    <div class="box" data-type="sandwich"><strong>Sandwiches</strong><div class="emoji">🥪</div></div>
    <div class="box" data-type="fruit"><strong>Fruit</strong><div class="emoji">🍎</div></div>
    <div class="box" data-type="drink"><strong>Drinks</strong><div class="emoji">🧃</div></div>
    <div class="box" data-type="treat"><strong>Treats</strong><div class="emoji">🧁</div></div>
  </section>

  <div class="controls">
    <button id="startBtn">Start Game</button>
    <button id="resetBtn">Reset</button>
    <div class="help">Drag or tap an item, then drop it into the matching lunchbox.</div>
  </div>
</div>

<div class="overlay" id="overlay">
  <div class="card">
    <h2>Pack Lunch Before Recess! 🛝</h2>
    <p>Food rolls by on the conveyor. Sort each item into the right lunchbox before it falls off the end.</p>
    <p><b>Sandwiches, fruit, drinks, and treats.</b></p>
    <button id="playBtn">Play</button>
  </div>
</div>

<script>
(() => {
  const playArea = document.getElementById("playArea");
  const boxes = [...document.querySelectorAll(".box")];
  const scoreEl = document.getElementById("score");
  const comboEl = document.getElementById("combo");
  const missesEl = document.getElementById("misses");
  const timeEl = document.getElementById("time");
  const overlay = document.getElementById("overlay");
  const playBtn = document.getElementById("playBtn");
  const startBtn = document.getElementById("startBtn");
  const resetBtn = document.getElementById("resetBtn");

  const foods = [
    { type: "sandwich", icon: "🥪" },
    { type: "sandwich", icon: "🌯" },
    { type: "fruit", icon: "🍎" },
    { type: "fruit", icon: "🍌" },
    { type: "fruit", icon: "🍇" },
    { type: "drink", icon: "🧃" },
    { type: "drink", icon: "🥛" },
    { type: "treat", icon: "🧁" },
    { type: "treat", icon: "🍪" }
  ];

  let running = false;
  let score = 0;
  let combo = 0;
  let misses = 0;
  let time = 60;
  let speed = 1.25;
  let spawnTimer = 0;
  let tickTimer = null;
  let animation = null;
  let items = [];
  let selected = null;

  function resetGame() {
    running = false;
    score = 0;
    combo = 0;
    misses = 0;
    time = 60;
    speed = 1.25;
    spawnTimer = 0;
    items.forEach(i => i.el.remove());
    items = [];
    updateHud();
    clearInterval(tickTimer);
    cancelAnimationFrame(animation);
  }

  function startGame() {
    resetGame();
    running = true;
    overlay.classList.add("hidden");
    tickTimer = setInterval(() => {
      if (!running) return;
      time--;
      speed += 0.035;
      updateHud();
      if (time <= 0) endGame("Recess Bell! 🔔");
    }, 1000);
    loop();
  }

  function updateHud() {
    scoreEl.textContent = score;
    comboEl.textContent = combo;
    missesEl.textContent = misses;
    timeEl.textContent = time;
  }

  function spawnItem() {
    const food = foods[Math.floor(Math.random() * foods.length)];
    const el = document.createElement("div");
    el.className = "item";
    el.textContent = food.icon;
    el.dataset.type = food.type;
    playArea.appendChild(el);

    const item = {
      el,
      type: food.type,
      x: -90,
      y: 70,
      held: false
    };

    el.style.left = item.x + "px";
    el.style.top = item.y + "px";

    el.addEventListener("pointerdown", e => {
      if (!running) return;
      e.preventDefault();
      selected = item;
      item.held = true;
      el.classList.add("dragging");
      el.setPointerCapture(e.pointerId);
    });

    el.addEventListener("pointermove", e => {
      if (!item.held) return;
      e.preventDefault();
      const r = playArea.getBoundingClientRect();
      item.x = e.clientX - r.left - el.offsetWidth / 2;
      item.y = e.clientY - r.top - el.offsetHeight / 2;
      place(item);
    });

    el.addEventListener("pointerup", e => {
      if (!item.held) return;
      item.held = false;
      el.classList.remove("dragging");
      checkDrop(item, e.clientX, e.clientY);
    });

    items.push(item);
  }

  function place(item) {
    item.el.style.left = item.x + "px";
    item.el.style.top = item.y + "px";
  }

  function checkDrop(item, clientX, clientY) {
    const target = boxes.find(box => {
      const r = box.getBoundingClientRect();
      return clientX >= r.left && clientX <= r.right && clientY >= r.top && clientY <= r.bottom;
    });

    if (!target) return;

    if (target.dataset.type === item.type) {
      combo++;
      score += 10 + combo * 2;
      flash(target, "good");
      removeItem(item);
    } else {
      combo = 0;
      misses++;
      flash(target, "bad");
      removeItem(item);
      if (misses >= 5) endGame("Lunch Disaster! 😵");
    }
    updateHud();
  }

  function flash(el, cls) {
    el.classList.add(cls);
    setTimeout(() => el.classList.remove(cls), 300);
  }

  function removeItem(item) {
    item.el.remove();
    items = items.filter(i => i !== item);
  }

  function loop() {
    if (!running) return;

    spawnTimer--;
    if (spawnTimer <= 0) {
      spawnItem();
      spawnTimer = Math.max(42, 95 - score / 8);
    }

    const areaWidth = playArea.clientWidth;
    for (const item of [...items]) {
      if (!item.held) {
        item.x += speed;
        place(item);
        if (item.x > areaWidth + 90) {
          combo = 0;
          misses++;
          removeItem(item);
          updateHud();
          if (misses >= 5) {
            endGame("Too Many Missed Lunches! 🥴");
            return;
          }
        }
      }
    }

    animation = requestAnimationFrame(loop);
  }

  function endGame(title) {
    running = false;
    clearInterval(tickTimer);
    cancelAnimationFrame(animation);
    overlay.classList.remove("hidden");
    overlay.querySelector(".card").innerHTML = `
      <h2>${title}</h2>
      <p>Your final score:</p>
      <h1>${score}</h1>
      <p>${score >= 350 ? "Lunchroom legend. 🏆" : score >= 200 ? "Solid packing shift. 🍱" : "Recess got messy, but recoverable. 😄"}</p>
      <button id="againBtn">Play Again</button>
    `;
    document.getElementById("againBtn").addEventListener("click", startGame);
  }

  playBtn.addEventListener("click", startGame);
  startBtn.addEventListener("click", startGame);
  resetBtn.addEventListener("click", () => {
    resetGame();
    overlay.classList.remove("hidden");
    overlay.querySelector(".card").innerHTML = `
      <h2>Pack Lunch Before Recess! 🛝</h2>
      <p>Food rolls by on the conveyor. Sort each item into the right lunchbox before it falls off the end.</p>
      <p><b>Sandwiches, fruit, drinks, and treats.</b></p>
      <button id="playBtn2">Play</button>
    `;
    document.getElementById("playBtn2").addEventListener("click", startGame);
  });

  updateHud();
})();
</script>
</body>
</html>

