    });

    items.push(item);
    updateSelection();
  }

  function place(item){ item.el.style.left=item.x+"px"; item.el.style.top=item.y+"px"; }

  function sortItem(item, box){
    if(!item || !box)return;
    if(box.dataset.type===item.type){
      combo++; score+=10+combo*2; flash(box,"good"); removeItem(item);
    } else {
      combo=0; misses++; flash(box,"bad"); removeItem(item); if(misses>=5)endGame("Lunch Disaster! 😵");
