        if(item.x>areaWidth+90){
          combo=0; misses++; removeItem(item); updateHud(); updateSelection();
          if(misses>=5){ endGame("Too Many Missed Lunches! 🥴"); return; }
        }
      }
    }
    animation=requestAnimationFrame(loop);
  }

  function endGame(title){
    running=false; clearInterval(tickTimer); cancelAnimationFrame(animation);
    overlay.classList.remove("hidden");
    overlay.querySelector(".card").innerHTML=`
      <h2>${title}</h2>
      <p>Your final score:</p>
      <h1>${score}</h1>
      <p>${score>=350?"Lunchroom legend. 🏆":score>=200?"Solid packing shift. 🍱":"Recess got messy, but recoverable. 😄"}</p>
      <button id="againBtn">Play Again</button>`;
    document.getElementById("againBtn").addEventListener("click",startGame);
  }

  function showStartCard(){
    overlay.classList.remove("hidden");
    overlay.querySelector(".card").innerHTML=`
      <h2>Pack Lunch Before Recess! 🛝</h2>
      <p>Sort each conveyor item into the right lunchbox before it falls off.</p>
      <p><b>Keyboard:</b> 1-4 sort instantly. ←/→ selects food. ↑/↓ selects lunchbox. Enter drops.</p>
      <button id="playBtn2">Play</button>`;
    document.getElementById("playBtn2").addEventListener("click",startGame);
  }

  window.addEventListener("keydown",e=>{
    if(!running){
      if(e.key==="Enter"||e.key===" "){ e.preventDefault(); startGame(); }
      return;
    }

    if(["ArrowLeft","ArrowRight","ArrowUp","ArrowDown","Enter"," ","1","2","3","4"].includes(e.key))e.preventDefault();

    if(e.key==="ArrowLeft"){
      selectedIndex=Math.max(0,selectedIndex-1);
    } else if(e.key==="ArrowRight"){
      selectedIndex=Math.min(items.length-1,selectedIndex+1);
    } else if(e.key==="ArrowUp"){
      targetBoxIndex=(targetBoxIndex+boxes.length-1)%boxes.length;
    } else if(e.key==="ArrowDown"){
      targetBoxIndex=(targetBoxIndex+1)%boxes.length;
    } else if(e.key==="Enter"||e.key===" "){
      sortItem(items[selectedIndex],boxes[targetBoxIndex]);
    } else if(["1","2","3","4"].includes(e.key)){
      sortItem(items[selectedIndex],boxes[Number(e.key)-1]);
    }

    updateSelection();
  });

  playBtn.addEventListener("click",startGame);
  startBtn.addEventListener("click",startGame);
  resetBtn.addEventListener("click",()=>{ resetGame(); showStartCard(); });

  updateHud();
})();
</script>
</body>
</html>

