<body>
<div class="game">
  <header>
    <h1>Lunchbox Conveyor</h1>
    <div class="hud">
      <div class="pill">Level: <span id="level">1</span>/3</div>
      <div class="pill">Packed: <span id="packed">0</span>/<span id="needed">8</span></div>
      <div class="pill">Score: <span id="score">0</span></div>
      <div class="pill">Misses: <span id="misses">0</span></div>
    </div>
  </header>

  <p class="goal" id="goalText">Goal: Pack 8 items.</p>

  <section class="panel belt-wrap" id="playArea"><div class="belt"></div></section>

  <section class="lunchboxes">
    <div class="box" data-type="sandwich"><strong>1 Sandwiches</strong><div class="emoji">🥪</div></div>
    <div class="box" data-type="fruit"><strong>2 Fruit</strong><div class="emoji">🍎</div></div>
    <div class="box" data-type="drink"><strong>3 Drinks</strong><div class="emoji">🧃</div></div>
    <div class="box" data-type="treat"><strong>4 Treats</strong><div class="emoji">🧁</div></div>
  </section>

  <div class="controls">
    <button id="startBtn">Start Game</button>
    <button id="resetBtn">Reset</button>
    <div class="help">Drag items, or use keyboard: 1 to 4 sort, ←/→ choose food, ↑/↓ choose lunchbox, Enter drops.</div>
  </div>
</div>

<div class="overlay" id="overlay">
  <div class="card">
    <h2>Lunch Rush Starts! 🛝</h2>
    <p>Level 1: Pack 8 items.</p>
    <p>Level 2: Pack 12 items with a faster belt.</p>
    <p>Level 3: Pack 10 mixed items with no mistakes.</p>
    <button id="playBtn">Play</button>
  </div>
</div>

<script>
(() => {
  const playArea = document.getElementById("playArea");
  const boxes = [...document.querySelectorAll(".box")];
  const levelEl = document.getElementById("level");
  const packedEl = document.getElementById("packed");
  const neededEl = document.getElementById("needed");
  const scoreEl = document.getElementById("score");
  const missesEl = document.getElementById("misses");
  const goalText = document.getElementById("goalText");
  const overlay = document.getElementById("overlay");
  const playBtn = document.getElementById("playBtn");
  const startBtn = document.getElementById("startBtn");
  const resetBtn = document.getElementById("resetBtn");

  const foods = [
    { type:"sandwich", icon:"🥪" }, { type:"sandwich", icon:"🌯" },
    { type:"fruit", icon:"🍎" }, { type:"fruit", icon:"🍌" }, { type:"fruit", icon:"🍇" },
    { type:"drink", icon:"🧃" }, { type:"drink", icon:"🥛" },
    { type:"treat", icon:"🧁" }, { type:"treat", icon:"🍪" }
  ];

  const levels = [
    { name:"Easy Pack", needed:8, speed:1.25, missesAllowed:5, goal:"Pack 8 items before they fall off." },
    { name:"Faster Belt", needed:12, speed:1.8, missesAllowed:5, goal:"Pack 12 items on a faster belt." },
    { name:"No Mistakes", needed:10, speed:1.55, missesAllowed:0, goal:"Pack 10 mixed items with no mistakes." }
  ];

  let running=false, levelIndex=0, score=0, packed=0, misses=0, speed=1.25, spawnTimer=0;
  let animation=null, items=[], selectedIndex=0, targetBoxIndex=0;

  function level(){ return levels[levelIndex]; }

  function resetGame(full=true){
    running=false;
    if(full){ levelIndex=0; score=0; }
    packed=0; misses=0; selectedIndex=0; targetBoxIndex=0; spawnTimer=0;
    speed=level().speed;
    items.forEach(i=>i.el.remove());
    items=[];
    cancelAnimationFrame(animation);
    updateHud();
    updateSelection();
  }

  function startGame(){
    resetGame(true);
    beginLevel();
  }

  function beginLevel(){
    resetGame(false);
    running=true;
    overlay.classList.add("hidden");
    updateHud();
    loop();
  }

  function updateHud(){
    levelEl.textContent=levelIndex+1;
    packedEl.textContent=packed;
    neededEl.textContent=level().needed;
    scoreEl.textContent=score;
    missesEl.textContent=misses + (level().missesAllowed === 0 ? "/0" : "/" + level().missesAllowed);
    goalText.textContent="Goal: " + level().goal;
  }

  function spawnItem(){
    const food=foods[Math.floor(Math.random()*foods.length)];
    const el=document.createElement("div");
    el.className="item";
    el.textContent=food.icon;
    el.dataset.type=food.type;
    playArea.appendChild(el);

    const item={el,type:food.type,x:-90,y:70,held:false};
    place(item);

    el.addEventListener("pointerdown",e=>{
      if(!running)return;
      e.preventDefault();
      selectedIndex=items.indexOf(item);
      item.held=true;
      el.classList.add("dragging");
      updateSelection();
      el.setPointerCapture(e.pointerId);
    });

    el.addEventListener("pointermove",e=>{
      if(!item.held)return;
      e.preventDefault();
      const r=playArea.getBoundingClientRect();
      item.x=e.clientX-r.left-el.offsetWidth/2;
      item.y=e.clientY-r.top-el.offsetHeight/2;
      place(item);
    });

    el.addEventListener("pointerup",e=>{
      if(!item.held)return;
      item.held=false;
      el.classList.remove("dragging");
      checkDrop(item,e.clientX,e.clientY);
    });

    items.push(item);
    updateSelection();
  }

  function place(item){
    item.el.style.left=item.x+"px";
    item.el.style.top=item.y+"px";
  }

  function sortItem(item, box){
    if(!running || !item || !box)return;

    if(box.dataset.type===item.type){
      packed++;
      score += levelIndex === 2 ? 18 : 12;
      flash(box,"good");
      removeItem(item);
      if(packed >= level().needed){
        completeLevel();
        return;
      }
    } else {
      addMistake(box);
      removeItem(item);
    }

    updateHud();
    updateSelection();
  }

  function addMistake(box){
    misses++;
    flash(box,"bad");
    if(level().missesAllowed === 0 || misses > level().missesAllowed){
      endGame("Lunch Rush Failed! 😵");
    }
  }

  function completeLevel(){
    running=false;
    cancelAnimationFrame(animation);
    items.forEach(i=>i.el.remove());
    items=[];

    if(levelIndex >= levels.length - 1){
      endGame("All Lunches Packed! 🏆");
      return;
    }

    levelIndex++;
    showLevelCard();
  }

  function showLevelCard(){
    overlay.classList.remove("hidden");
    overlay.querySelector(".card").innerHTML=`
      <h2>Level ${levelIndex + 1}: ${level().name}</h2>
      <p>${level().goal}</p>
      <p>Score so far: <b>${score}</b></p>
      <button id="nextBtn">Start Level</button>`;
    document.getElementById("nextBtn").addEventListener("click",beginLevel);
    updateHud();
  }

  function checkDrop(item, clientX, clientY){
    const target=boxes.find(box=>{
      const r=box.getBoundingClientRect();
      return clientX>=r.left&&clientX<=r.right&&clientY>=r.top&&clientY<=r.bottom;
    });
    if(target)sortItem(item,target);
  }

  function flash(el,cls){
    el.classList.add(cls);
    setTimeout(()=>el.classList.remove(cls),300);
  }

  function removeItem(item){
    item.el.remove();
    items=items.filter(i=>i!==item);
    if(selectedIndex>=items.length)selectedIndex=Math.max(0,items.length-1);
  }

  function updateSelection(){
    items.forEach(i=>i.el.classList.remove("selected"));
    boxes.forEach(b=>b.classList.remove("target"));
    if(items[selectedIndex])items[selectedIndex].el.classList.add("selected");
    if(boxes[targetBoxIndex])boxes[targetBoxIndex].classList.add("target");
  }

  function loop(){
    if(!running)return;

    spawnTimer--;
    if(spawnTimer<=0){
      spawnItem();
      spawnTimer=Math.max(38,90-(levelIndex*14)-(packed*2));
    }

    const areaWidth=playArea.clientWidth;
    for(const item of [...items]){
      if(!item.held){
        item.x+=speed;
        place(item);
        if(item.x>areaWidth+90){
          removeItem(item);
          addMistake(boxes[targetBoxIndex]);
          updateHud();
          updateSelection();
          if(!running)return;
        }
      }
    }

    animation=requestAnimationFrame(loop);
  }

  function endGame(title){
    running=false;
    cancelAnimationFrame(animation);
    overlay.classList.remove("hidden");
    overlay.querySelector(".card").innerHTML=`
      <h2>${title}</h2>
      <p>Final score:</p>
      <h1>${score}</h1>
      <p>Reached Level ${levelIndex + 1}. Packed ${packed}/${level().needed} in this round.</p>
      <button id="againBtn">Play Again</button>`;
    document.getElementById("againBtn").addEventListener("click",startGame);
  }

  function showStartCard(){
    resetGame(true);
    overlay.classList.remove("hidden");
    overlay.querySelector(".card").innerHTML=`
      <h2>Lunch Rush Starts! 🛝</h2>
      <p>Level 1: Pack 8 items.</p>
      <p>Level 2: Pack 12 items with a faster belt.</p>
      <p>Level 3: Pack 10 mixed items with no mistakes.</p>
      <button id="playBtn2">Play</button>`;
    document.getElementById("playBtn2").addEventListener("click",startGame);
  }

  window.addEventListener("keydown",e=>{
    if(!running){
      if(e.key==="Enter"||e.key===" "){
        e.preventDefault();
        const btn=overlay.querySelector("button");
        if(btn)btn.click();
      }
      return;
    }

    if(["ArrowLeft","ArrowRight","ArrowUp","ArrowDown","Enter"," ","1","2","3","4"].includes(e.key))e.preventDefault();

    if(e.key==="ArrowLeft")selectedIndex=Math.max(0,selectedIndex-1);
    else if(e.key==="ArrowRight")selectedIndex=Math.min(items.length-1,selectedIndex+1);
    else if(e.key==="ArrowUp")targetBoxIndex=(targetBoxIndex+boxes.length-1)%boxes.length;
    else if(e.key==="ArrowDown")targetBoxIndex=(targetBoxIndex+1)%boxes.length;
    else if(e.key==="Enter"||e.key===" ")sortItem(items[selectedIndex],boxes[targetBoxIndex]);
    else if(["1","2","3","4"].includes(e.key))sortItem(items[selectedIndex],boxes[Number(e.key)-1]);

    updateSelection();
  });

  playBtn.addEventListener("click",startGame);
  startBtn.addEventListener("click",startGame);
  resetBtn.addEventListener("click",showStartCard);

  updateHud();
})();
</script>
</body>
</html>

