    { type:"sandwich", label:"Sandwich", icon:"🥪" }, { type:"sandwich", label:"Wrap", icon:"🌯" },
    { type:"fruit", label:"Apple", icon:"🍎" }, { type:"fruit", label:"Banana", icon:"🍌" }, { type:"fruit", label:"Grapes", icon:"🍇" },
    { type:"drink", label:"Juice Box", icon:"🧃" }, { type:"drink", label:"Milk", icon:"🥛" },
    { type:"treat", label:"Cupcake", icon:"🧁" }, { type:"treat", label:"Cookie", icon:"🍪" }
  ];

  const levels = [
    { name:"Easy Pack", needed:8, speed:1.25, missesAllowed:5, goal:"Pack 8 items before they fall off." },
    { name:"Faster Belt", needed:12, speed:1.8, missesAllowed:5, goal:"Pack 12 items on a faster belt." },
    { name:"No Mistakes", needed:10, speed:1.55, missesAllowed:0, goal:"Pack 10 mixed items with no mistakes." }
  ];

