    el.classList.add(cls);
    setTimeout(()=>el.classList.remove(cls),300);
  }

  function removeItem(item){
    item.el.remove();
    items=items.filter(i=>i!==item);
    if(selectedIndex>=items.length)selectedIndex=Math.max(0,items.length-1);
  }

  function updateSelection(){
    items.forEach(i=>i.el.classList.remove("selected"));
    boxes.forEach(b=>b.classList.remove("target"));

    const selected=items[selectedIndex];
    const target=boxes[targetBoxIndex];

    if(selected){
      selected.el.classList.add("selected");
      selectedText.textContent="Selected food: " + selected.icon + " " + selected.label;
    } else {
      selectedText.textContent=running ? "Selected food: waiting for next item" : "Selected food: none yet";
    }

    if(target){
      target.classList.add("target");
      targetText.textContent="Target lunchbox: " + target.dataset.label;
    }
  }

  function loop(){
    if(!running)return;

    spawnTimer--;
    if(spawnTimer<=0){
      spawnItem();
      spawnTimer=Math.max(38,90-(levelIndex*14)-(packed*2));
    }

    const areaWidth=playArea.clientWidth;
